

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .create_embedding_response_object import CreateEmbeddingResponseObject
from .create_embedding_response_usage import CreateEmbeddingResponseUsage
from .embedding import Embedding


class CreateEmbeddingResponse(UniversalBaseModel):
    data: typing.List[Embedding] = pydantic.Field()
    """
    The list of embeddings generated by the model.
    """

    model: str = pydantic.Field()
    """
    The name of the model used to generate the embedding.
    """

    object: CreateEmbeddingResponseObject = pydantic.Field()
    """
    The object type, which is always "list".
    """

    usage: CreateEmbeddingResponseUsage = pydantic.Field()
    """
    The usage information for the request.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
